import { Controller, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

function numericText(raw: unknown): string | null {
  if (typeof raw === 'number' && Number.isFinite(raw)) {
    return String(raw);
  }
  if (typeof raw === 'string' && /^-?\d+(\.\d+)?$/.test(raw.trim())) {
    return raw.trim();
  }
  return null;
}

function idText(raw: unknown): string | null {
  if (typeof raw === 'number' && Number.isInteger(raw) && raw > 0) {
    return String(raw);
  }
  if (typeof raw === 'string' && /^\d{1,18}$/.test(raw.trim())) {
    return raw.trim();
  }
  return null;
}

@Controller('api/v1')
export class FnSfr01903Controller {
  @Post('/annual-leaves/:annualLeaveId/adjust')
  @HttpCode(200)
  async adjustAnnualLeave(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    const annualLeaveId = idText(req.params['annualLeaveId']);
    if (annualLeaveId === null) {
      throw new ApiError(404, 'ANNUAL_LEAVE_NOT_FOUND', '대상 연차를 찾을 수 없습니다.');
    }
    const days = numericText(data['adjustedDays']);
    if (days === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조정 일수는 숫자로 입력해야 합니다.');
    }
    const reasonRaw = data['changeReason'];
    const reason = typeof reasonRaw === 'string' ? reasonRaw.trim() : '';
    if (reason === '') {
      throw new ApiError(422, 'INVALID_LEAVE_ADJUSTMENT', '조정 사유를 입력해야 합니다.');
    }
    if (reason.length > 500) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조정 사유는 500자 이하로 입력해야 합니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT confirm_status AS "confirmStatus",
                COALESCE(granted_days, 0) + COALESCE(adjusted_days, 0) + CAST(:days AS numeric) - COALESCE(used_days, 0) AS "remain"
           FROM annual_leave
          WHERE annual_leave_id = CAST(:annualLeaveId AS bigint)
          FOR UPDATE`,
        { days, annualLeaveId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ANNUAL_LEAVE_NOT_FOUND', '대상 연차를 찾을 수 없습니다.');
      }
      // 확정된 연차만 조정할 수 있다 (전환: 확정 -> 조정)
      if (rows[0]['confirmStatus'] !== '확정') {
        throw new ApiError(409, 'INVALID_STATE', '확정된 연차만 조정할 수 있습니다.');
      }
      if (Number(rows[0]['remain']) < 0) {
        throw new ApiError(422, 'INVALID_LEAVE_ADJUSTMENT', '조정 후 잔여 연차가 음수가 될 수 없습니다.');
      }
      const updated = await db.query(
        `UPDATE annual_leave
            SET adjusted_days = COALESCE(adjusted_days, 0) + CAST(:days AS numeric),
                updated_at = now()
          WHERE annual_leave_id = CAST(:annualLeaveId AS bigint)
          RETURNING annual_leave_id AS "annualLeaveId", adjusted_days AS "adjustedDays"`,
        { days, annualLeaveId },
      );
      // 가정: 변경 내용 문장은 개발 담당자가 정한다
      await db.execute(
        `INSERT INTO annual_leave_history
           (annual_leave_id, changer_id, change_type, changed_at, change_days, change_content, change_reason, created_at, updated_at)
         VALUES
           (CAST(:annualLeaveId AS bigint), CAST(:userId AS bigint), '조정', now(), CAST(:days AS numeric), :content, :reason, now(), now())`,
        {
          annualLeaveId,
          userId: user.id,
          days,
          content: '연차 조정 ' + days + '일',
          reason,
        },
      );
      return updated[0];
    });
  }

  @Post('/annual-leave-settlements')
  @HttpCode(200)
  async createAnnualLeaveSettlement(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    const annualLeaveId = idText(data['annualLeaveId']);
    if (annualLeaveId === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '연차를 선택해야 합니다.');
    }
    const baseRaw = data['settlementBaseDate'];
    if (typeof baseRaw !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(baseRaw.trim())) {
      throw new ApiError(400, 'VALIDATION_FAILED', '정산 기준일을 YYYY-MM-DD 형식으로 입력해야 합니다.');
    }
    const baseDate = baseRaw.trim();
    return transaction(async (db) => {
      const leaves = await db.query(
        `SELECT confirm_status AS "confirmStatus"
           FROM annual_leave
          WHERE annual_leave_id = CAST(:annualLeaveId AS bigint)
          FOR UPDATE`,
        { annualLeaveId },
      );
      if (leaves.length === 0) {
        throw new ApiError(404, 'ANNUAL_LEAVE_NOT_FOUND', '대상 연차를 찾을 수 없습니다.');
      }
      if (leaves[0]['confirmStatus'] !== '확정') {
        throw new ApiError(422, 'ANNUAL_LEAVE_NOT_CONFIRMED', '확정되지 않은 연차는 정산할 수 없습니다.');
      }
      const done = await db.query(
        `SELECT annual_leave_settlement_id AS "id"
           FROM annual_leave_settlement
          WHERE annual_leave_id = CAST(:annualLeaveId AS bigint)`,
        { annualLeaveId },
      );
      if (done.length > 0) {
        throw new ApiError(409, 'SETTLEMENT_ALREADY_COMPLETED', '이미 정산 완료된 연차입니다.');
      }
      // 미사용 일수 = 확정 일수(+조정 일수) - 사용 일수, 0 미만은 0
      const rows = await db.query(
        `INSERT INTO annual_leave_settlement
           (annual_leave_id, settlement_base_date, unused_days, settlement_amount, created_at, updated_at)
         SELECT al.annual_leave_id,
                CAST(:baseDate AS date),
                GREATEST(COALESCE(al.granted_days, 0) + COALESCE(al.adjusted_days, 0) - COALESCE(al.used_days, 0), 0),
                NULL,
                now(),
                now()
           FROM annual_leave al
          WHERE al.annual_leave_id = CAST(:annualLeaveId AS bigint)
         RETURNING annual_leave_settlement_id AS "annualLeaveSettlementId",
                   unused_days AS "unusedDays",
                   settlement_amount AS "settlementAmount"`,
        { annualLeaveId, baseDate },
      );
      return rows[0];
    });
  }
}

