import { useState } from 'react';
import type { PageProps, Row } from '../kit';
import {
  call,
  Badge,
  Num,
  DateText,
  Tiles,
  Band,
  DataTable,
  Drawer,
  Form,
  Field,
  NumberInput,
  TextInput,
  DateInput,
  LookupSelect,
  RefName,
} from '../kit';

type Mode = 'adjust' | 'settle' | null;

export default function FnSfr01903Page({ role, notify }: PageProps) {
  const [mode, setMode] = useState<Mode>(null);
  const [results, setResults] = useState<Row[]>([]);
  const [annualLeaveId, setAnnualLeaveId] = useState<number | string>('');
  const [adjustedDays, setAdjustedDays] = useState<number | string>('');
  const [changeReason, setChangeReason] = useState('');
  const [baseDate, setBaseDate] = useState('');

  function open(next: Mode) {
    setAnnualLeaveId('');
    setAdjustedDays('');
    setChangeReason('');
    setBaseDate('');
    setMode(next);
  }

  async function submitAdjust() {
    if (annualLeaveId === '') {
      throw new Error('연차를 선택해야 합니다.');
    }
    if (adjustedDays === '') {
      throw new Error('가감할 조정 일수를 입력해야 합니다.');
    }
    if (changeReason.trim() === '') {
      throw new Error('조정 사유를 입력해야 합니다.');
    }
    const res = await call('POST', '/annual-leaves/' + annualLeaveId + '/adjust', role, {
      adjustedDays,
      changeReason,
    });
    setResults([{ kind: '조정', ...res }, ...results]);
    notify('연차를 조정했습니다.');
    setMode(null);
  }

  async function submitSettle() {
    if (annualLeaveId === '') {
      throw new Error('연차를 선택해야 합니다.');
    }
    if (baseDate === '') {
      throw new Error('정산 기준일을 입력해야 합니다.');
    }
    const res = await call('POST', '/annual-leave-settlements', role, {
      annualLeaveId,
      settlementBaseDate: baseDate,
    });
    setResults([{ kind: '정산', annualLeaveId, settlementBaseDate: baseDate, ...res }, ...results]);
    notify('미사용 연차를 정산했습니다.');
    setMode(null);
  }

  const adjustCount = results.filter((r) => r['kind'] === '조정').length;
  const settleCount = results.filter((r) => r['kind'] === '정산').length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['조정 건수', <Num value={adjustCount} />],
            ['정산 건수', <Num value={settleCount} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>처리 결과</h2>
        <Band total={results.length}>
          <button type="button" onClick={() => open('adjust')}>연차 조정</button>
          <button type="button" onClick={() => open('settle')}>미사용 연차 정산</button>
        </Band>
        <DataTable
          rows={results}
          empty="이 화면에서 처리한 내역이 없습니다."
          columns={[
            { key: 'kind', label: '구분', render: (r) => <Badge value={r['kind']} /> },
            {
              key: 'annualLeaveId',
              label: '연차',
              render: (r) => <RefName table="annual_leave" role={role} value={r['annualLeaveId']} />,
            },
            { key: 'adjustedDays', label: '조정 일수', render: (r) => <Num value={r['adjustedDays']} /> },
            {
              key: 'settlementBaseDate',
              label: '정산 기준일',
              render: (r) => <DateText value={r['settlementBaseDate']} />,
            },
            { key: 'unusedDays', label: '미사용 연차 일수', render: (r) => <Num value={r['unusedDays']} /> },
            { key: 'settlementAmount', label: '정산 금액', render: (r) => <Num value={r['settlementAmount']} /> },
          ]}
        />
      </section>
      {mode === 'adjust' && (
        <Drawer title="연차 조정" onClose={() => setMode(null)}>
          <Form onSubmit={submitAdjust} submit="조정">
            <Field label="연차 ID" required>
              <LookupSelect table="annual_leave" role={role} value={annualLeaveId} onChange={setAnnualLeaveId} />
            </Field>
            <Field label="가감할 조정 일수" required>
              <NumberInput value={adjustedDays} onChange={setAdjustedDays} />
            </Field>
            <Field label="조정 사유" required wide>
              <TextInput value={changeReason} onChange={setChangeReason} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'settle' && (
        <Drawer title="미사용 연차 정산" onClose={() => setMode(null)}>
          <Form onSubmit={submitSettle} submit="정산">
            <Field label="연차 ID" required>
              <LookupSelect table="annual_leave" role={role} value={annualLeaveId} onChange={setAnnualLeaveId} />
            </Field>
            <Field label="정산 기준일" required>
              <DateInput value={baseDate} onChange={setBaseDate} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
